type View = "home" | "login" | "signup" | "dashboard" | "problems" | "practice" | "analysis" | "analytics" | "history";

type InterviewQuestion = { question: string; answer: string };
type Problem = { title: string; topic: string; difficulty: "Easy" | "Medium" | "Hard"; solved: boolean; attempts: number; time: string };
type Language = "Python" | "Java" | "C++" | "C" | "JavaScript" | "Go" | "Rust";
const languages: Language[] = ["Python", "Java", "C++", "C", "JavaScript", "Go", "Rust"];
type SubmissionRecord = { title: string; language: Language; time: string; date: string; status: "Accepted" | "Needs review"; at?: number };
type ProgressData = { solved: Record<string, { attempts: number; time: string }>; attempts: Record<string, number>; submissions: SubmissionRecord[] };
const emptyProgress: ProgressData = { solved: {}, attempts: {}, submissions: [] };
const progressStorageKey = (user: StoredUser | null) => `syntaxfit-progress-${user?.email || "guest"}`;
const readProgress = (user: StoredUser | null): ProgressData => { try { const raw = localStorage.getItem(progressStorageKey(user)); return raw ? { ...emptyProgress, ...JSON.parse(raw), attempts: JSON.parse(raw).attempts || {} } : emptyProgress; } catch { return emptyProgress; } };
const starterForLanguage = (problem: Problem, detail: ProblemDetail, language: Language): string => {
  if (detail.templates?.[language]) return detail.templates[language] as string;
  if (language === "Java") return detail.starterCode;
  if (language === "Python") return `# ${problem.title}\ndef solve(input_data):\n    # Implement the ${problem.title} pattern here\n    pass`;
  if (language === "C++") return `#include <bits/stdc++.h>\nusing namespace std;\n\nclass Solution {\npublic:\n    // ${problem.title}: implement the solution here\n};`;
  if (language === "C") return `#include <stdio.h>\n\n/* ${problem.title}: implement the solution here */\nint main(void) {\n    return 0;\n}`;
  if (language === "JavaScript") return `// ${problem.title}\nfunction solve(input) {\n  // Implement the solution here\n  return null;\n}`;
  if (language === "Go") return `package main\n\n// ${problem.title}\nfunc solve(input any) any {\n    // Implement the solution here\n    return nil\n}`;
  return `// ${problem.title}\nfn solve() {\n    // Implement the solution here\n}`;
};

const isToday = (submission: SubmissionRecord) => submission.at ? new Date(submission.at).toDateString() === new Date().toDateString() : submission.date === "Today";
const weeklyActivity = (submissions: SubmissionRecord[]) => Array.from({ length: 7 }, (_, index) => { const day = new Date(); day.setHours(0, 0, 0, 0); day.setDate(day.getDate() - (6 - index)); const nextDay = new Date(day); nextDay.setDate(day.getDate() + 1); const count = submissions.filter(item => { const at = item.at ? new Date(item.at) : item.date === "Today" ? new Date() : null; return at ? at >= day && at < nextDay : false; }).length; return { label: day.toLocaleDateString("en-US", { weekday: "short" }).slice(0, 1), count, today: index === 6 }; });
type ExampleCase = { input: string; output: string; why: string };
type ProblemDetail = {
  statement: string; input: string; output: string; why: string; examples?: ExampleCase[]; constraints: string[]; lens: string;
  starterCode: string; templates?: Partial<Record<Language, string>>; brute: string; optimal: string; time: string; space: string; questions: InterviewQuestion[];
};

type StoredUser = { fullName: string; username: string; email: string; password: string };
