const SESSION_STORAGE_KEY = "syntaxcompilefit-session";
const readStoredUser = (): StoredUser | null => { try { const raw = localStorage.getItem(USER_STORAGE_KEY); return raw ? JSON.parse(raw) as StoredUser : null; } catch { return null; } };
const readStoredSession = (): StoredUser | null => { try { const raw = localStorage.getItem(SESSION_STORAGE_KEY); return raw ? JSON.parse(raw) as StoredUser : null; } catch { return null; } };
const userInitials = (fullName: string) => fullName.split(" ").filter(Boolean).map(part => part[0]).join("").slice(0, 2).toUpperCase() || "ST";

